<?php
if(PHP_SAPI!=='cli'){http_response_code(403);exit(1);}$base=dirname(__DIR__);require $base.'/app/Config/App.php';require $base.'/app/Support/helpers.php';App\Config\App::loadEnv($base);
$opt=getopt('',['dry-run','apply','confirm:','limit:','payment-id:','database:']);$apply=isset($opt['apply']);if($apply&&($opt['confirm']??'')!=='RECONCILIAR'){fwrite(STDERR,"Use --apply --confirm=RECONCILIAR.\n");exit(2);}$limit=max(1,min(1000,(int)($opt['limit']??100)));$dbName=$opt['database']??app_env('DB_DATABASE','');if(!preg_match('/^[A-Za-z0-9_-]+$/',(string)$dbName))exit(2);
$pdo=new PDO('mysql:host='.app_env('DB_HOST').';port='.app_env('DB_PORT').';dbname='.$dbName.';charset=utf8mb4',app_env('DB_USERNAME'),app_env('DB_PASSWORD'),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$where="status='approved' AND total>0";$params=[];if(!empty($opt['payment-id'])){$where.=' AND payment_id=:payment';$params[':payment']=$opt['payment-id'];}$sql="SELECT external_reference,payment_id,total,updated_at,created_at,financeiro_lancado_at FROM mercado_pago_pedidos WHERE $where ORDER BY created_at,external_reference LIMIT $limit";$stmt=$pdo->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();$pending=[];$done=0;
foreach($rows as$r){$q=$pdo->prepare("SELECT COUNT(*) FROM financeiro WHERE tipo='Receita' AND categoria='Venda Site (Mercado Pago)' AND descricao LIKE :ref");$q->execute([':ref'=>'%'.$r['external_reference'].'%']);if($r['financeiro_lancado_at']||((int)$q->fetchColumn()>0))$done++;else$pending[]=$r;}
echo 'Analisados='.count($rows).' pendentes='.count($pending).' conciliados='.$done.PHP_EOL;if(!$apply){echo "DRY-RUN: nenhuma alteração realizada.\n";exit(0);}try{$pdo->beginTransaction();$ins=$pdo->prepare("INSERT INTO financeiro(tipo,categoria,descricao,valor,os_id,usuario_id,data_pagamento,forma_pagamento) VALUES('Receita','Venda Site (Mercado Pago)',:descricao,:valor,NULL,NULL,:data,'Mercado Pago')");$up=$pdo->prepare('UPDATE mercado_pago_pedidos SET financeiro_lancado_at=NOW() WHERE external_reference=:ref AND financeiro_lancado_at IS NULL');foreach($pending as$r){$ins->execute([':descricao'=>'Venda site Mercado Pago '.$r['external_reference'].(!empty($r['payment_id'])?' - Pagamento '.$r['payment_id']:''),':valor'=>$r['total'],':data'=>date('Y-m-d',strtotime($r['updated_at']?:$r['created_at']))]);$up->execute([':ref'=>$r['external_reference']]);}$pdo->commit();echo 'Aplicado='.count($pending).PHP_EOL;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();fwrite(STDERR,"Falha; lote revertido.\n");exit(3);}
